import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { Client, types } from 'pg';
import { PrismaService } from 'src/database/prisma.service';
import { encrypt, decrypt } from './crypto.util';
import { validateSelectQuery } from './sql-validator';
import {
  CreateDataSourceDto,
  UpdateDataSourceDto,
  ExecuteQueryDto,
} from './datasource.dto';

const QUERY_TIMEOUT_MS = 30_000;
const MAX_ROWS = 10_000;

// Keep date/time types as raw Postgres text instead of JS `Date`, which the
// default parser shifts by the Node runtime timezone. (TIME/TIMETZ are strings.)
const RAW_TEXT_OIDS = new Set([
  types.builtins.DATE,
  types.builtins.TIMESTAMP,
  types.builtins.TIMESTAMPTZ,
]);

// pg-types types getTypeParser's return as `any`; pin it to avoid leaking `any`.
type ValueParser = (value: string) => unknown;
const getDefaultParser = types.getTypeParser as (
  oid: Parameters<typeof types.getTypeParser>[0],
  format?: Parameters<typeof types.getTypeParser>[1],
) => ValueParser;

const datasourceTypeParser: typeof types.getTypeParser = (oid, format) =>
  RAW_TEXT_OIDS.has(oid)
    ? (value: string) => value
    : getDefaultParser(oid, format);

@Injectable()
export class DataSourceService {
  constructor(private prisma: PrismaService) {}

  async create(userId: number, workspaceId: string, dto: CreateDataSourceDto) {
    return this.prisma.dataSource.create({
      data: {
        name: dto.name,
        host: dto.host,
        port: dto.port ?? 5432,
        database: dto.database,
        username: dto.username,
        password: encrypt(dto.password),
        sslEnabled: dto.sslEnabled ?? false,
        authorID: userId,
        workspaceId,
      },
    });
  }

  async findAllByWorkspace(workspaceId: string) {
    const datasources = await this.prisma.dataSource.findMany({
      where: { workspaceId },
      orderBy: { createdAt: 'desc' },
    });

    // Mask passwords
    return datasources.map((ds) => ({
      ...ds,
      password: '********',
    }));
  }

  async findOne(id: string) {
    const ds = await this.prisma.dataSource.findUnique({ where: { id } });
    if (!ds) {
      throw new NotFoundException('DataSource not found');
    }
    return { ...ds, password: '********' };
  }

  async update(id: string, dto: UpdateDataSourceDto) {
    const ds = await this.prisma.dataSource.findUnique({ where: { id } });
    if (!ds) {
      throw new NotFoundException('DataSource not found');
    }

    const data: Record<string, unknown> = {};
    if (dto.name !== undefined) data.name = dto.name;
    if (dto.host !== undefined) data.host = dto.host;
    if (dto.port !== undefined) data.port = dto.port;
    if (dto.database !== undefined) data.database = dto.database;
    if (dto.username !== undefined) data.username = dto.username;
    if (dto.password !== undefined) data.password = encrypt(dto.password);
    if (dto.sslEnabled !== undefined) data.sslEnabled = dto.sslEnabled;

    return this.prisma.dataSource.update({
      where: { id },
      data,
    });
  }

  async remove(id: string) {
    const ds = await this.prisma.dataSource.findUnique({ where: { id } });
    if (!ds) {
      throw new NotFoundException('DataSource not found');
    }
    return this.prisma.dataSource.delete({ where: { id } });
  }

  async testConnection(id: string) {
    const ds = await this.prisma.dataSource.findUnique({ where: { id } });
    if (!ds) {
      throw new NotFoundException('DataSource not found');
    }

    const client = this.createClient(ds);
    try {
      await client.connect();
      await client.query('SELECT 1');
      return { success: true };
    } catch (error) {
      return { success: false, error: (error as Error).message };
    } finally {
      await client.end().catch(() => {});
    }
  }

  async executeQuery(id: string, dto: ExecuteQueryDto) {
    const validation = validateSelectQuery(dto.query);
    if (!validation.valid) {
      throw new BadRequestException(validation.error);
    }

    const ds = await this.prisma.dataSource.findUnique({ where: { id } });
    if (!ds) {
      throw new NotFoundException('DataSource not found');
    }

    const client = this.createClient(ds);
    try {
      await client.connect();

      // Set statement timeout
      await client.query(`SET statement_timeout = '${QUERY_TIMEOUT_MS}'`);
      await client.query(`SET TimeZone = 'UTC'`);
      await client.query(`SET DateStyle = 'ISO, MDY'`);

      // Wrap with LIMIT to enforce max rows
      const wrappedQuery = `SELECT * FROM (${dto.query}) AS _q LIMIT ${MAX_ROWS + 1}`;
      const startTime = Date.now();
      const result = await client.query(wrappedQuery);
      const executionTime = Date.now() - startTime;

      const truncated = result.rows.length > MAX_ROWS;
      const rows = truncated ? result.rows.slice(0, MAX_ROWS) : result.rows;

      return {
        columns: result.fields.map((f) => ({
          name: f.name,
          dataTypeID: f.dataTypeID,
        })),
        rows,
        rowCount: rows.length,
        truncated,
        executionTime,
      };
    } catch (error) {
      const pgError = error as { message?: string; code?: string };
      throw new BadRequestException(
        pgError.message || 'Query execution failed',
      );
    } finally {
      await client.end().catch(() => {});
    }
  }

  /**
   * Retrieve the raw datasource record (with workspaceId) for access
   * control checks in the controller layer.
   */
  async findRaw(id: string) {
    const ds = await this.prisma.dataSource.findUnique({ where: { id } });
    if (!ds) {
      throw new NotFoundException('DataSource not found');
    }
    return ds;
  }

  private createClient(ds: {
    host: string;
    port: number;
    database: string;
    username: string;
    password: string;
    sslEnabled: boolean;
  }): Client {
    return new Client({
      host: ds.host,
      port: ds.port,
      database: ds.database,
      user: ds.username,
      password: decrypt(ds.password),
      ssl: ds.sslEnabled ? { rejectUnauthorized: false } : false,
      connectionTimeoutMillis: 10_000,
      types: { getTypeParser: datasourceTypeParser },
    });
  }
}

import {
  IsBoolean,
  IsInt,
  IsOptional,
  IsString,
  IsUUID,
  Length,
  Max,
  Min,
} from 'class-validator';

export class CreateDataSourceDto {
  @IsString()
  @Length(1, 100)
  name: string;

  @IsString()
  @Length(1, 253)
  host: string;

  @IsOptional()
  @IsInt()
  @Min(1)
  @Max(65535)
  port?: number;

  @IsString()
  @Length(1, 100)
  database: string;

  @IsString()
  @Length(1, 100)
  username: string;

  @IsString()
  @Length(0, 256)
  password: string;

  @IsOptional()
  @IsBoolean()
  sslEnabled?: boolean;
}

export class CreateDataSourceInWorkspaceDto extends CreateDataSourceDto {
  @IsUUID()
  workspaceId: string;
}

export class UpdateDataSourceDto {
  @IsOptional()
  @IsString()
  @Length(1, 100)
  name?: string;

  @IsOptional()
  @IsString()
  @Length(1, 253)
  host?: string;

  @IsOptional()
  @IsInt()
  @Min(1)
  @Max(65535)
  port?: number;

  @IsOptional()
  @IsString()
  @Length(1, 100)
  database?: string;

  @IsOptional()
  @IsString()
  @Length(1, 100)
  username?: string;

  @IsOptional()
  @IsString()
  @Length(0, 256)
  password?: string;

  @IsOptional()
  @IsBoolean()
  sslEnabled?: boolean;
}

export class ExecuteQueryDto {
  @IsString()
  @Length(1, 100_000)
  query: string;
}

import {
  Controller,
  Get,
  Post,
  Patch,
  Delete,
  Body,
  Param,
  Req,
  UseGuards,
} from '@nestjs/common';
import { DataSourceService } from './datasource.service';
import {
  CreateDataSourceDto,
  CreateDataSourceInWorkspaceDto,
  UpdateDataSourceDto,
  ExecuteQueryDto,
} from './datasource.dto';
import { JwtAuthGuard } from 'src/auth/jwt-auth.guard';
import { AuthenticatedRequest } from 'src/auth/auth.types';
import { WorkspaceService } from '../workspace/workspace.service';

@Controller()
@UseGuards(JwtAuthGuard)
export class DataSourceController {
  constructor(
    private readonly datasourceService: DataSourceService,
    private readonly workspaceService: WorkspaceService,
  ) {}

  // --- Workspace-scoped endpoints ---

  @Post('workspaces/:workspaceId/datasources')
  async createInWorkspace(
    @Param('workspaceId') workspaceIdOrSlug: string,
    @Req() req: AuthenticatedRequest,
    @Body() dto: CreateDataSourceDto,
  ) {
    const userId = Number(req.user.id);
    const workspaceId =
      await this.workspaceService.resolveId(workspaceIdOrSlug);
    await this.workspaceService.assertMember(workspaceId, userId);
    return this.datasourceService.create(userId, workspaceId, dto);
  }

  @Get('workspaces/:workspaceId/datasources')
  async findByWorkspace(
    @Param('workspaceId') workspaceIdOrSlug: string,
    @Req() req: AuthenticatedRequest,
  ) {
    const userId = Number(req.user.id);
    const workspaceId =
      await this.workspaceService.resolveId(workspaceIdOrSlug);
    await this.workspaceService.assertMember(workspaceId, userId);
    return this.datasourceService.findAllByWorkspace(workspaceId);
  }

  // --- Legacy / backward-compatible endpoints ---

  @Post('datasources')
  async create(
    @Req() req: AuthenticatedRequest,
    @Body() dto: CreateDataSourceInWorkspaceDto,
  ) {
    const userId = Number(req.user.id);
    await this.workspaceService.assertMember(dto.workspaceId, userId);
    return this.datasourceService.create(userId, dto.workspaceId, dto);
  }

  @Get('datasources')
  async findAll(@Req() req: AuthenticatedRequest) {
    const userId = Number(req.user.id);
    const workspaces = await this.workspaceService.findAllByUser(userId);
    const results = await Promise.all(
      workspaces.map((w) => this.datasourceService.findAllByWorkspace(w.id)),
    );
    return results.flat();
  }

  @Get('datasources/:id')
  async findOne(
    @Req() req: AuthenticatedRequest,
    @Param('id') id: string,
  ) {
    const ds = await this.datasourceService.findRaw(id);
    await this.workspaceService.assertMember(
      ds.workspaceId,
      Number(req.user.id),
    );
    return this.datasourceService.findOne(id);
  }

  @Patch('datasources/:id')
  async update(
    @Req() req: AuthenticatedRequest,
    @Param('id') id: string,
    @Body() dto: UpdateDataSourceDto,
  ) {
    const ds = await this.datasourceService.findRaw(id);
    await this.workspaceService.assertMember(
      ds.workspaceId,
      Number(req.user.id),
    );
    return this.datasourceService.update(id, dto);
  }

  @Delete('datasources/:id')
  async remove(
    @Req() req: AuthenticatedRequest,
    @Param('id') id: string,
  ) {
    const ds = await this.datasourceService.findRaw(id);
    await this.workspaceService.assertMember(
      ds.workspaceId,
      Number(req.user.id),
    );
    return this.datasourceService.remove(id);
  }

  @Post('datasources/:id/test')
  async testConnection(
    @Req() req: AuthenticatedRequest,
    @Param('id') id: string,
  ) {
    const ds = await this.datasourceService.findRaw(id);
    await this.workspaceService.assertMember(
      ds.workspaceId,
      Number(req.user.id),
    );
    return this.datasourceService.testConnection(id);
  }

  @Post('datasources/:id/query')
  async executeQuery(
    @Req() req: AuthenticatedRequest,
    @Param('id') id: string,
    @Body() dto: ExecuteQueryDto,
  ) {
    const ds = await this.datasourceService.findRaw(id);
    await this.workspaceService.assertMember(
      ds.workspaceId,
      Number(req.user.id),
    );
    return this.datasourceService.executeQuery(id, dto);
  }
}

const FORBIDDEN_KEYWORDS = [
  'INSERT',
  'UPDATE',
  'DELETE',
  'DROP',
  'ALTER',
  'CREATE',
  'TRUNCATE',
  'GRANT',
  'REVOKE',
  'EXEC',
  'EXECUTE',
];

/**
 * Validates that a SQL query is a single read-only SELECT statement.
 */
export function validateSelectQuery(sql: string): {
  valid: boolean;
  error?: string;
} {
  const trimmed = sql.trim();
  if (!trimmed) {
    return { valid: false, error: 'Query cannot be empty' };
  }

  // Strip SQL comments (-- line comments and /* block comments */)
  const withoutComments = trimmed
    .replace(/--[^\n]*/g, '')
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .trim();

  if (!withoutComments) {
    return { valid: false, error: 'Query cannot be empty after removing comments' };
  }

  // Check the first meaningful token is SELECT or WITH (for CTEs)
  const firstToken = withoutComments.split(/\s+/)[0].toUpperCase();
  if (firstToken !== 'SELECT' && firstToken !== 'WITH') {
    return {
      valid: false,
      error: 'Only SELECT queries are allowed',
    };
  }

  // Check for forbidden keywords as standalone tokens
  const upperSql = withoutComments.toUpperCase();
  for (const keyword of FORBIDDEN_KEYWORDS) {
    // Match keyword as a whole word (not part of column/table names)
    const regex = new RegExp(`\\b${keyword}\\b`, 'i');
    if (regex.test(upperSql)) {
      return {
        valid: false,
        error: `Forbidden keyword: ${keyword}`,
      };
    }
  }

  // Check for multiple statements (semicolons followed by non-whitespace)
  const withoutStrings = withoutComments.replace(/'[^']*'/g, '');
  const statements = withoutStrings.split(';').filter((s) => s.trim().length > 0);
  if (statements.length > 1) {
    return {
      valid: false,
      error: 'Multiple statements are not allowed',
    };
  }

  return { valid: true };
}

import { validateSelectQuery } from './sql-validator';

describe('validateSelectQuery', () => {
  it('accepts simple SELECT queries', () => {
    expect(validateSelectQuery('SELECT * FROM users')).toEqual({ valid: true });
  });

  it('accepts CTE queries and strips comments', () => {
    const sql = `
      -- get active users
      WITH active_users AS (
        SELECT id FROM users WHERE active = true
      )
      SELECT * FROM active_users
    `;

    expect(validateSelectQuery(sql)).toEqual({ valid: true });
  });

  it('rejects empty queries', () => {
    expect(validateSelectQuery('   ')).toEqual({
      valid: false,
      error: 'Query cannot be empty',
    });
  });

  it('rejects non-SELECT first tokens', () => {
    expect(validateSelectQuery('DELETE FROM users')).toEqual({
      valid: false,
      error: 'Only SELECT queries are allowed',
    });
  });

  it('rejects forbidden keywords', () => {
    expect(validateSelectQuery('SELECT id FROM users; DROP TABLE users')).toEqual(
      {
        valid: false,
        error: 'Forbidden keyword: DROP',
      },
    );
  });

  it('rejects multiple statements', () => {
    expect(validateSelectQuery('SELECT 1; SELECT 2')).toEqual({
      valid: false,
      error: 'Multiple statements are not allowed',
    });
  });
});

import { parseRef, toSref } from '../model/core/coordinates';
import {
  Axis,
  Cell,
  CellStyle,
  ConditionalFormatRule,
  FilterState,
  HiddenState,
  PivotTableDefinition,
  Grid,
  MergeSpan,
  Ref,
  Range,
  Sref,
  Direction,
} from '../model/core/types';
import type {
  CellAnchor,
  RangeAnchor,
  SelectionPresence,
} from '../model/workbook/anchor-conversion';
import { RangeStylePatch } from '../model/worksheet/range-styles';
import type { Comment, Thread } from '../comment/types';
import { CellIndex } from './cell-index';
import { findEdgeWithIndex } from './find-edge';
import { Store } from './store';

/**
 * Converts a raw query result value to a string suitable for a sheet cell.
 * Date → ISO string, object → JSON, everything else → String().
 */
export function toCell(val: unknown): string {
  if (val instanceof Date) return val.toISOString();
  if (typeof val === 'object' && val !== null) return JSON.stringify(val);
  return String(val);
}

/**
 * `ReadOnlyStore` is a Store implementation for displaying query results.
 * All write operations are no-ops. Data is loaded via `loadQueryResults`.
 */
export class ReadOnlyStore implements Store {
  private grid: Map<Sref, Cell> = new Map();
  private cellIndex: CellIndex = new CellIndex();

  /**
   * Loads query result data into the store.
   * Row 1 contains column headers (bold), rows 2+ contain data.
   * Uses 1-based indices to match the sheet coordinate system.
   */
  loadQueryResults(
    columns: Array<{ name: string }>,
    rows: Array<Record<string, unknown>>,
  ): void {
    this.grid.clear();

    // Row 1: column headers (1-based)
    for (let c = 0; c < columns.length; c++) {
      const sref = toSref({ r: 1, c: c + 1 });
      this.grid.set(sref, {
        v: columns[c].name,
        s: { b: true },
      });
    }

    // Row 2+: data rows (1-based)
    for (let r = 0; r < rows.length; r++) {
      const row = rows[r];
      for (let c = 0; c < columns.length; c++) {
        const val = row[columns[c].name];
        if (val === null || val === undefined) continue;
        const sref = toSref({ r: r + 2, c: c + 1 });
        this.grid.set(sref, { v: toCell(val) });
      }
    }

    this.rebuildIndex();
  }

  async set(_ref: Ref, _value: Cell): Promise<void> {
    // no-op
  }

  async get(ref: Ref): Promise<Cell | undefined> {
    return this.grid.get(toSref(ref));
  }

  async has(ref: Ref): Promise<boolean> {
    return this.grid.has(toSref(ref));
  }

  async delete(_ref: Ref): Promise<boolean> {
    return false;
  }

  async deleteRange(_range: Range): Promise<Set<Sref>> {
    return new Set();
  }

  async setGrid(_grid: Grid): Promise<void> {
    // no-op
  }

  async getGrid(range: Range): Promise<Grid> {
    const grid: Grid = new Map();
    for (const [row, col] of this.cellIndex.cellsInRange(range)) {
      const sref = toSref({ r: row, c: col });
      const value = this.grid.get(sref);
      if (value !== undefined) {
        grid.set(sref, value);
      }
    }
    return grid;
  }

  async findEdge(
    ref: Ref,
    direction: Direction,
    dimension: Range,
  ): Promise<Ref> {
    return findEdgeWithIndex(
      this.cellIndex,
      ref,
      direction,
      dimension,
      (r, c) => {
        const cell = this.grid.get(toSref({ r, c }));
        return cell !== undefined && (!!cell.v || !!cell.f);
      },
    );
  }

  async shiftCells(_axis: Axis, _index: number, _count: number): Promise<void> {
    // no-op
  }

  async moveCells(
    _axis: Axis,
    _srcIndex: number,
    _count: number,
    _dstIndex: number,
  ): Promise<void> {
    // no-op
  }

  async buildDependantsMap(
    _srefs: Iterable<Sref>,
  ): Promise<Map<Sref, Set<Sref>>> {
    return new Map();
  }

  async getFormulaGrid(): Promise<Grid> {
    return new Map();
  }

  getPresences(): Array<{
    clientID: string;
    presence: {
      selection?: SelectionPresence;
      activeCell?: string;
      username?: string;
    };
  }> {
    return [];
  }

  updateSelection(
    _activeCell: CellAnchor | null,
    _ranges: RangeAnchor[],
    _activeCellRef: Ref,
  ): void {
    // no-op
  }

  getRowOrder(): string[] {
    return [];
  }

  getColOrder(): string[] {
    return [];
  }

  ensureAxisOrder(_minRows: number, _minCols: number): void {
    // no-op
  }

  async setDimensionSize(
    _axis: Axis,
    _index: number,
    _size: number,
  ): Promise<void> {
    // no-op
  }

  async getDimensionSizes(_axis: Axis): Promise<Map<number, number>> {
    return new Map();
  }

  async setColumnStyle(_col: number, _style: CellStyle): Promise<void> {
    // no-op
  }

  async getColumnStyles(): Promise<Map<number, CellStyle>> {
    return new Map();
  }

  async setRowStyle(_row: number, _style: CellStyle): Promise<void> {
    // no-op
  }

  async getRowStyles(): Promise<Map<number, CellStyle>> {
    return new Map();
  }

  async setSheetStyle(_style: CellStyle): Promise<void> {
    // no-op
  }

  async getSheetStyle(): Promise<CellStyle | undefined> {
    return undefined;
  }

  async addRangeStyle(_patch: RangeStylePatch): Promise<void> {
    // no-op
  }

  async setRangeStyles(_patches: RangeStylePatch[]): Promise<void> {
    // no-op
  }

  async getRangeStyles(): Promise<RangeStylePatch[]> {
    return [];
  }

  async setConditionalFormats(_rules: ConditionalFormatRule[]): Promise<void> {
    // no-op
  }

  async getConditionalFormats(): Promise<ConditionalFormatRule[]> {
    return [];
  }

  async setMerge(_anchor: Ref, _span: MergeSpan): Promise<void> {
    // no-op
  }

  async deleteMerge(_anchor: Ref): Promise<boolean> {
    return false;
  }

  async getMerges(): Promise<Map<Sref, MergeSpan>> {
    return new Map();
  }

  async setFilterState(_state: FilterState | undefined): Promise<void> {
    // no-op
  }

  async getFilterState(): Promise<FilterState | undefined> {
    return undefined;
  }

  async setHiddenState(_state: HiddenState | undefined): Promise<void> {
    // no-op
  }

  async getHiddenState(): Promise<HiddenState | undefined> {
    return undefined;
  }

  async setPivotDefinition(
    _def: PivotTableDefinition | undefined,
  ): Promise<void> {
    // no-op
  }

  async getPivotDefinition(): Promise<PivotTableDefinition | undefined> {
    return undefined;
  }

  async setFreezePane(_frozenRows: number, _frozenCols: number): Promise<void> {
    // no-op
  }

  async getFreezePane(): Promise<{ frozenRows: number; frozenCols: number }> {
    return { frozenRows: 0, frozenCols: 0 };
  }

  beginBatch(): void {
    // no-op
  }

  endBatch(): void {
    // no-op
  }

  async undo(): Promise<{ success: boolean }> {
    return { success: false };
  }

  async redo(): Promise<{ success: boolean }> {
    return { success: false };
  }

  canUndo(): boolean {
    return false;
  }

  canRedo(): boolean {
    return false;
  }

  invalidate(): void {
    this.rebuildIndex();
  }

  private rebuildIndex(): void {
    this.cellIndex.rebuild(
      Array.from(this.grid.keys()).map((sref) => {
        const ref = parseRef(sref);
        return [ref.r, ref.c];
      }),
    );
  }

  async addThread(): Promise<Thread> {
    throw new Error('Read-only store: addThread not allowed');
  }

  async addReply(): Promise<Comment> {
    throw new Error('Read-only store: addReply not allowed');
  }

  async editComment(): Promise<void> {
    throw new Error('Read-only store: editComment not allowed');
  }

  async deleteComment(): Promise<void> {
    throw new Error('Read-only store: deleteComment not allowed');
  }

  async setThreadResolved(): Promise<void> {
    throw new Error('Read-only store: setThreadResolved not allowed');
  }

  async listThreads(): Promise<Thread[]> {
    return [];
  }
}

import {
  BadRequestException,
  ForbiddenException,
  GoneException,
} from '@nestjs/common';
import { Test, TestingModule } from '@nestjs/testing';
import { Client, types } from 'pg';
import { toCell } from '@wafflebase/sheets';
import { PrismaService } from 'src/database/prisma.service';
import { DataSourceService } from 'src/datasource/datasource.service';
import { ShareLinkService } from 'src/share-link/share-link.service';
import {
  describeDb,
  parseDatabaseUrl,
  clearDatabase,
  createUserFactory,
  createWorkspace,
  setIntegrationEnvDefaults,
} from './helpers/integration-helpers';

describeDb('Database-backed integration', () => {
  let moduleRef: TestingModule;
